  "J'offre des fleurs à ma mère.": {
   "file": "audio/tts/qwen3-fr-bf16/537ee1a5403de252.mp3",
   "voiceId": "qwen3-fr-bf16",
   "duration": 1.7
  },
  "J'oublie toujours son nom.": {
   "file": "audio/tts/qwen3-fr-bf16/81f9a1ca61b10f33.mp3",
   "voiceId": "qwen3-fr-bf16",
   "duration": 1.2
  },
  "J'utilise mon téléphone pour apprendre le français.": {
   "file": "audio/tts/qwen3-fr-bf16/9e2e9ddf9f787ac9.mp3",
   "voiceId": "qwen3-fr-bf16",
   "duration": 2.38
  },
  "J'écoute de la musique dans le métro.": {
   "file": "audio/tts/qwen3-fr-bf16/4220379aafbc779a.mp3",
   "voiceId": "qwen3-fr-bf16",
   "duration": 2.0
  },
  "J'écris une lettre à ma grand-mère.": {
   "file": "audio/tts/qwen3-fr-bf16/3599a23aa6b694a3.mp3",
   "voiceId": "qwen3-fr-bf16",
   "duration": 1.66
  },
  "J'étudie le français le soir.": {
   "file": "audio/tts/qwen3-fr-bf16/7b8e8f08774d3a71.mp3",
   "voiceId": "qwen3-fr-bf16",
   "duration": 1.76
  },
  "Je bois un café chaque matin.": {
   "file": "audio/tts/qwen3-fr-bf16/cb323609b7b1847a.mp3",
   "voiceId": "qwen3-fr-bf16",
   "duration": 1.58
  },
  "Je cherche la gare.": {
   "file": "audio/tts/qwen3-fr-bf16/611474df0b58daaa.mp3",
   "voiceId": "qwen3-fr-bf16",
   "duration": 0.94
  },
  "Je choisis la tarte aux pommes.": {
   "file": "audio/tts/qwen3-fr-bf16/2b2f89b1f9a73f8f.mp3",
   "voiceId": "qwen3-fr-bf16",
   "duration": 1.66
  },
  "Je compte partir en juillet.": {
   "file": "audio/tts/qwen3-fr-bf16/f3c3fc982a179c4d.mp3",
   "voiceId": "qwen3-fr-bf16",
   "duration": 1.6
  },
  "Je couche les enfants à 20 h.": {
   "file": "audio/tts/qwen3-fr-bf16/397c6643b17438aa.mp3",
   "voiceId": "qwen3-fr-bf16",
   "duration": 1.84
  },
  "Je cours dans le parc le dimanche.": {
   "file": "audio/tts/qwen3-fr-bf16/9bb2b61a56226915.mp3",
   "voiceId": "qwen3-fr-bf16",
   "duration": 1.84
  },
  "Je crois qu'il va pleuvoir.": {
   "file": "audio/tts/qwen3-fr-bf16/da3264910784a2e8.mp3",
   "voiceId": "qwen3-fr-bf16",
   "duration": 1.44
  },
